SELECT (SELECT code FROM promotions x WHERE x.promo_id = r.promo_id) AS c, COUNT(r.redemption_id) AS u FROM promotion_redemptions r JOIN orders o USING (order_id) WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2025-10-01 00:00:00' AND o.order_at < TIMESTAMP '2026-01-01 00:00:00' GROUP BY r.promo_id ORDER BY u DESC, c LIMIT 5
